"""Stabilizer-based fixed-Clifford sensing; no auxiliary qubits or setting mixing.

Uses the independently dense-checked Pauli QFIM kernel from the N<=5 study.
All axis signs are chosen before loss/encoding. Nothing is adapted to loss.
"""
from collections import Counter
from functools import lru_cache
from itertools import permutations, product
from fractions import Fraction
import hashlib
import json
from math import comb
from pathlib import Path
import sys
import numpy as np

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT.parent))
from fixed_clifford_sensors.engine import (AXES, GATES, unsigned_profiles,
                                          effective_information)


def decode_graph6(line):
    n = line[0]-63
    if not 1 <= n <= 7:
        raise ValueError("Only graph6 files for 1..7 vertices are bundled")
    bits = [(c-63 >> k) & 1 for c in line[1:] for k in range(5, -1, -1)]
    adjacent, position = [0]*n, 0
    for j in range(1, n):
        for i in range(j):
            if bits[position]:
                adjacent[i] |= 1 << j
                adjacent[j] |= 1 << i
            position += 1
    return tuple(adjacent)


@lru_cache(None)
def connected_graphs(n):
    path = ROOT/"data"/f"vncorbits{n}.g6"
    record = next(s for s in json.loads((ROOT/"data/sources.json").read_text()) if s["vertices"] == n)
    if hashlib.sha256(path.read_bytes()).hexdigest() != record["sha256"]:
        raise ArithmeticError("Graph catalogue input hash mismatch")
    graphs = tuple(decode_graph6(line) for line in path.read_bytes().splitlines() if line)
    if len(graphs) != record["connected_classes"]:
        raise ArithmeticError("Connected graph count mismatch")
    return graphs


@lru_cache(None)
def catalogue(n):
    """Connected LC representatives AND all multisets of smaller components."""
    shapes = [(k, i) for k in range(1, n+1) for i in range(len(connected_graphs(k)))]

    def partitions(left, start=0):
        if left == 0:
            yield ()
            return
        for index in range(start, len(shapes)):
            k, i = shapes[index]
            if k > left:
                break
            for rest in partitions(left-k, index):
                yield ((k, i),)+rest

    graphs = []
    for components in partitions(n):
        adjacent, offset = [], 0
        for k, i in components:
            adjacent.extend(row << offset for row in connected_graphs(k)[i])
            offset += k
        edges = [[i, j] for i in range(n) for j in range(i+1, n) if adjacent[i] >> j & 1]
        graphs.append({"components": components, "adjacent": tuple(adjacent), "edges": edges})
    expected = [0, 1, 2, 3, 6, 11, 26, 59][n]
    if len(graphs) != expected:
        raise ArithmeticError("Total LC catalogue count mismatch")
    return tuple(graphs)


def automorphisms(adjacent):
    """Exact graph automorphism group, generated by degree-compatible permutations."""
    n, groups = len(adjacent), {}
    for i, row in enumerate(adjacent):
        groups.setdefault(row.bit_count(), []).append(i)
    groups = list(groups.values())
    edges = [(i, j) for i in range(n) for j in range(i+1, n) if adjacent[i] >> j & 1]
    result = []
    for chunks in product(*(permutations(g) for g in groups)):
        perm = list(range(n))
        for group, chunk in zip(groups, chunks):
            for i, j in zip(group, chunk):
                perm[i] = j
        if all(adjacent[perm[i]] >> perm[j] & 1 for i, j in edges):
            result.append(tuple(perm))
    return tuple(result)


def axis_orbits(adjacent, reduction="symmetry"):
    """Unsigned Pauli axes; an isolated |+> sensor must not use effective X.

    Returns representative axes with orbit multiplicities and an independent
    Burnside count. Signs are subsequently obtained from stabilizer correlations.
    """
    palettes = [(1, 2) if row == 0 else (0, 1, 2) for row in adjacent]
    unseen = set(product(*palettes))
    raw_count = len(unseen)
    if reduction == "none":
        return [(axes, 1) for axes in sorted(unseen)], raw_count, raw_count, 1
    group = automorphisms(adjacent)
    burnside_sum = 0
    for perm in group:
        seen, fixed = set(), 1
        for i in range(len(adjacent)):
            if i in seen:
                continue
            fixed *= len(palettes[i])
            j = i
            while j not in seen:
                seen.add(j)
                j = perm[j]
        burnside_sum += fixed
    burnside = burnside_sum // len(group)
    if burnside_sum % len(group):
        raise ArithmeticError("Nonintegral orbit count")
    orbits = []
    while unseen:
        axes = min(unseen)
        orbit = {tuple(axes[p[i]] for i in range(len(adjacent))) for p in group}
        unseen.difference_update(orbit)
        orbits.append((axes, len(orbit)))
    if len(orbits) != burnside or sum(size for _, size in orbits) != raw_count:
        raise ArithmeticError("Orbit coverage mismatch")
    return orbits, raw_count, burnside, len(group)


def aligned_signs(q):
    """Find the unique useful sign class for the uniform mean.

    Pure stabilizer/Pauli QFIMs consist of signed rank-one all-ones blocks.
    A negative relative sign inside a block makes the all-positive mean
    unidentifiable. Global sign changes per block do not change any loss QFIM.
    """
    n = len(q)
    if not np.all(np.diag(q) == 1):
        return None, None
    signs = np.ones(n, dtype=np.int8)
    seen, blocks = set(), []
    for root in range(n):
        if root in seen:
            continue
        seen.add(root)
        todo, block = [root], []
        while todo:
            i = todo.pop()
            block.append(i)
            for j in range(n):
                if i == j or q[i, j] == 0:
                    continue
                sign = signs[i]*int(q[i, j])
                if j in seen:
                    if signs[j] != sign:
                        raise ArithmeticError("Frustrated stabilizer pair correlations")
                else:
                    signs[j] = sign
                    seen.add(j)
                    todo.append(j)
        blocks.append(tuple(sorted(block)))
    expected = np.zeros_like(q)
    for block in blocks:
        expected[np.ix_(block, block)] = 1
    if not np.array_equal(q*signs[:, None]*signs[None, :], expected):
        raise ArithmeticError("Pure QFIM is not a signed block projector")
    return signs, tuple(blocks)


def aggregate_profile(profile):
    n = profile.shape[-1]
    counts = np.array([s.bit_count() for s in range(1 << n)])
    return np.stack([profile[counts == k].sum(axis=0, dtype=np.int16) for k in range(n+1)])


def block_signature(aggregate, blocks):
    """Canonical unlabeled QFIM polynomial, derived from stabilizer blocks.

    This removes equivalent-information configurations even between different
    graph representatives. No claim of local-Clifford state equivalence is made.
    """
    expected = np.zeros_like(aggregate)
    signature = []
    for block in blocks:
        coefficients = tuple(int(x) for x in aggregate[:, block[0], block[0]])
        n, size = aggregate.shape[-1], len(block)
        for k, c in enumerate(coefficients):
            maximum = comb(n-size, k-size) if k >= size else 0
            if not 0 <= c <= maximum:
                raise ArithmeticError("Block QFI survives a missing member or exceeds erasure probability")
        signature.append((len(block), coefficients))
        for i in block:
            for j in block:
                expected[:, i, j] = coefficients
    if not np.array_equal(expected, aggregate):
        raise ArithmeticError("Loss-averaged QFIM violates the pure-state block support")
    return tuple(sorted(signature))


def score_signature(signature, etas):
    n = sum(size for size, _ in signature)
    k = np.arange(n+1)
    etas = np.asarray(etas, dtype=float)
    weights = etas[:, None]**k*(1-etas[:, None])**(n-k)
    activities = np.array([weights@np.array(coefficients) for _, coefficients in signature])
    good = np.all(activities > 0, axis=0)
    denominators = np.sum(np.divide(1., activities, out=np.zeros_like(activities), where=activities > 0), axis=0)
    return np.divide(n, denominators, out=np.zeros_like(denominators), where=good)


def exact_score(signature, eta):
    n = sum(size for size, _ in signature)
    eta = Fraction(eta)
    denominator = Fraction(0)
    for _, coefficients in signature:
        activity = sum(Fraction(c)*eta**k*(1-eta)**(n-k) for k, c in enumerate(coefficients))
        if activity == 0:
            return Fraction(0)
        denominator += 1/activity
    return Fraction(n)/denominator


def protocol(n, graph_id, item, choices, signs, blocks, aggregate, signature):
    axes = [("+" if s > 0 else "-")+AXES[a] for a, s in zip(choices, signs)]
    return {"n": n, "graph_id": graph_id, "components": item["components"],
            "edges": item["edges"], "effective_axes": axes,
            "sensor_gates": [GATES[a] for a in axes], "correlation_blocks": blocks,
            "A_by_survivor_count": aggregate.tolist(), "signature": signature}


def integer_partitions(n, minimum=1):
    if n == 0:
        yield ()
    for k in range(minimum, n+1):
        for rest in integer_partitions(n-k, k):
            yield (k,)+rest


def ghz_partition_score(partition, eta):
    eta = Fraction(eta)
    return Fraction(sum(partition))/sum(eta**(-k) for k in partition) if eta else Fraction(0)


def signature_dominance_bound(signature, etas):
    """Any lost member of a pure rank-one correlation block destroys its QFI.

    Thus activity of a size-k block is <= eta**k, achieved by an independent
    GHZ_k. This is an upper bound, never used to skip the exhaustive search.
    """
    partition = tuple(size for size, _ in signature)
    return np.array([float(ghz_partition_score(partition, str(eta))) for eta in etas])
